import{_ as a}from"./chunks/my-system.CS4oEI92.js";import{_ as o,o as e,c as l,ai as r}from"./chunks/framework.C33Uq6m-.js";const u=JSON.parse('{"title":"我的系统","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/system.md","filePath":"zh/guide/system.md"}'),i={name:"zh/guide/system.md"};function s(n,t,d,c,h,m){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="我的系统" tabindex="-1">我的系统 <a class="header-anchor" href="#我的系统" aria-label="Permalink to &quot;我的系统&quot;">​</a></h1><p>系统页显示真实的硬件规格和 Ollama 的实时状态 —— 这些是直接来自操作系统的数据，而不是浏览器的估算。</p><p><strong>侧边栏位置：</strong> 我的系统 <strong>路由：</strong> <code>/system</code></p><p><img src="'+a+'" alt="我的系统界面"></p><h2 id="硬件检测" tabindex="-1">硬件检测 <a class="header-anchor" href="#硬件检测" aria-label="Permalink to &quot;硬件检测&quot;">​</a></h2><p>LLMxRay 使用一个自定义的 Vite 插件（<code>vite-plugin-system-info</code>）直接向操作系统查询：</p><table tabindex="0"><thead><tr><th>平台</th><th>检测方式</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td>PowerShell 命令</td></tr><tr><td><strong>Linux</strong></td><td><code>/proc</code> 文件系统 + <code>lspci</code></td></tr><tr><td><strong>macOS</strong></td><td><code>sysctl</code> 命令</td></tr></tbody></table><h3 id="显示的信息" tabindex="-1">显示的信息 <a class="header-anchor" href="#显示的信息" aria-label="Permalink to &quot;显示的信息&quot;">​</a></h3><ul><li><strong>CPU</strong> —— 型号名称、核心数、架构</li><li><strong>内存</strong> —— 已安装总容量及实时占用</li><li><strong>GPU</strong> —— 型号名称、显存、驱动版本</li><li><strong>存储</strong> —— 磁盘容量与可用空间</li></ul><div class="tip custom-block"><p class="custom-block-title">首次使用</p><p>硬件信息是在 Vite 开发服务器启动时读取的。如果系统页显示「请重启开发服务器」，请停止并重新运行 <code>npm run dev</code>。</p></div><h2 id="ollama-状态" tabindex="-1">Ollama 状态 <a class="header-anchor" href="#ollama-状态" aria-label="Permalink to &quot;Ollama 状态&quot;">​</a></h2><p>Ollama 区块显示：</p><ul><li><strong>连接状态</strong> —— Ollama 是否可访问</li><li><strong>运行中的模型</strong> —— 当前载入内存的模型</li><li><strong>内存占用</strong> —— 每个已载入模型占用的内存 / 显存</li><li><strong>推理设置</strong> —— 当前实例的默认参数</li></ul><h2 id="存储占用" tabindex="-1">存储占用 <a class="header-anchor" href="#存储占用" aria-label="Permalink to &quot;存储占用&quot;">​</a></h2><p>LLMxRay 所用 IndexedDB 存储的可视化：</p><ul><li>该来源占用的总存储量</li><li>按数据库分类的细分（对话、基准测试、RAG 向量、训练数据）</li><li>可视化的百分比条</li></ul><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li><strong>内存占用很高？</strong> —— Ollama 在首次使用后会把模型留在内存中。可以改用量化程度更高的小模型（Q4），或在设置中调小上下文长度。</li><li><strong>检测不到 GPU？</strong> —— 请确认显卡驱动是最新的。在 Linux 上，请确保 <code>lspci</code> 可用。</li><li>每次进入本页时，存储可视化都会自动刷新。</li></ul>',18)])])}const _=o(i,[["render",s]]);export{u as __pageData,_ as default};
